package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="purchase_invoice_line")public class LineaFacturaProveedor{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_invoice_id",nullable=false)private FacturaProveedor factura;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="product_id",nullable=false)private UUID productoId;@Column(name="product_code_snapshot",length=24)private String productoCodigo;@Column(name="description_snapshot",nullable=false,length=500)private String descripcion;@Column(name="unit_snapshot",length=120)private String unidad;@Column(nullable=false,precision=19,scale=4)private BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=19,scale=4)private BigDecimal precio;@Column(name="discount_amount",nullable=false,precision=19,scale=4)private BigDecimal descuento;@Column(name="tax_id")private UUID impuestoId;@Column(name="tax_name_snapshot",length=120)private String impuestoNombre;@Column(name="tax_rate_snapshot",nullable=false,precision=9,scale=6)private BigDecimal impuestoTasa;@Column(name="tax_amount",nullable=false,precision=19,scale=4)private BigDecimal impuesto;@Column(name="line_subtotal",nullable=false,precision=19,scale=4)private BigDecimal subtotal;@Column(name="line_total",nullable=false,precision=19,scale=4)private BigDecimal total;@Column(name="line_order",nullable=false)private int ordenLinea;@Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadaEn;protected LineaFacturaProveedor(){}public LineaFacturaProveedor(UUID t,UUID e,UUID p,String c,String d,String u,BigDecimal q,BigDecimal pr,BigDecimal de,UUID ti,String tn,BigDecimal tr,BigDecimal ta,BigDecimal st,BigDecimal to,int o){tenantId=t;empresaId=e;productoId=p;productoCodigo=c;descripcion=d;unidad=u;quantity=q;precio=pr;descuento=de;impuestoId=ti;impuestoNombre=tn;impuestoTasa=tr;impuesto=ta;subtotal=st;total=to;ordenLinea=o;}void asignar(FacturaProveedor f){factura=f;}public UUID getProductoId(){return productoId;}public String getProductoCodigo(){return productoCodigo;}public String getDescripcion(){return descripcion;}public String getUnidad(){return unidad;}public BigDecimal getCantidad(){return quantity;}public BigDecimal getPrecio(){return precio;}public BigDecimal getDescuento(){return descuento;}public UUID getImpuestoId(){return impuestoId;}public String getImpuestoNombre(){return impuestoNombre;}public BigDecimal getImpuestoTasa(){return impuestoTasa;}public BigDecimal getImpuesto(){return impuesto;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTotal(){return total;}public int getOrdenLinea(){return ordenLinea;}}
